import {ssrSafeLocation} from '@github-ui/ssr-utils'

const STORAGE_KEY_PREFIX = 'copilot-generate-pull-title'

/**
 * Returns the session storage key for the pull title, scoped to the current page pathname.
 * This ensures that different PR creation pages don't share the same stored title.
 */
export function getPullTitleStorageKey(): string {
  return `${STORAGE_KEY_PREFIX}:${ssrSafeLocation.pathname}`
}
