import {useClickAnalytics} from '@github-ui/use-analytics'
import {useCallback} from 'react'

// Based on https://www.npmjs.com/package/string-similarity-js
function stringSimilarity(str1: string, str2: string, substringLength: number, caseSensitive: boolean): number {
  if (!caseSensitive) {
    str1 = str1.toLowerCase()
    str2 = str2.toLowerCase()
  }

  if (str1.length < substringLength || str2.length < substringLength) return 0

  const map = new Map<string, number>()
  for (let i = 0; i < str1.length - (substringLength - 1); i++) {
    const substr1 = str1.slice(i, i + substringLength)
    map.set(substr1, (map.get(substr1) ?? 0) + 1)
  }

  let match = 0
  for (let j = 0; j < str2.length - (substringLength - 1); j++) {
    const substr2 = str2.slice(j, j + substringLength)
    const count = map.get(substr2) ?? 0
    if (count > 0) {
      map.set(substr2, count - 1)
      match++
    }
  }

  return (match * 2) / (str1.length + str2.length - (substringLength - 1) * 2)
}

export function useTrackPullTitleAcceptance() {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  return useCallback(
    ({
      title,
      defaultTitle,
      generatedTitle,
      regenerateCallCount,
    }: {
      title: string
      defaultTitle: string
      generatedTitle?: string | null
      regenerateCallCount: number
    }): void => {
      // Only track if we've generated at least once
      if (regenerateCallCount === 0) {
        return
      }

      const eventData = {
        category: 'copilot_generate_pull_title',
        action: 'submit',
        default_title_similarity: stringSimilarity(title, defaultTitle, 2, false),
        submitted_title_similarity: stringSimilarity(title, generatedTitle ?? '', 2, false),
        regenerate_call_count: regenerateCallCount,
      }

      sendClickAnalyticsEvent(eventData)
    },
    [sendClickAnalyticsEvent],
  )
}
