import type {Commit} from '../types'

// Rough estimate of token count (4 characters per token)
const CHARACTERS_PER_TOKEN = 4

export function calculateInputTokenUsage(commits: Commit[]): number {
  const requestCharCount = commits.reduce((total, commit) => {
    return total + commit.oid.length + commit.message.length
  }, 0)
  return Math.ceil(requestCharCount / CHARACTERS_PER_TOKEN)
}
